import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const MAX_ATTEMPTS = 3;
const STEP_MS = 100;
const RETRY_DELAY_MS = 500;
const POLL_MS = 100;

const db = openDatabase();
let stopping = false;
const wake = new AbortController();

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    wake.abort();
  });
}

const beatStmt = db.prepare(
  'INSERT INTO heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at',
);
function beat(): void {
  try {
    beatStmt.run(Date.now());
  } catch (err) {
    console.error('heartbeat failed', err);
  }
}
beat();
const beatTimer = setInterval(beat, 500);

const now = () => new Date().toISOString();

// Any job left `running` belongs to a worker that died; put it back in the queue.
db.prepare("UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, updated_at = ? WHERE status = 'running'").run(now());

const pickStmt = db.prepare(
  "SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq ASC LIMIT 1",
);
const claimStmt = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = MIN(attempts + 1, ${MAX_ATTEMPTS}), progress = 0, updated_at = ?
   WHERE id = ? AND status = 'queued'`,
);
const getStmt = db.prepare('SELECT * FROM jobs WHERE id = ?');
const progressStmt = db.prepare("UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'");
const completeStmt = db.prepare(
  "UPDATE jobs SET status = 'completed', progress = steps, output = ?, error = NULL, updated_at = ? WHERE id = ? AND status = 'running'",
);
const retryStmt = db.prepare(
  "UPDATE jobs SET status = 'queued', progress = 0, run_after = ?, updated_at = ? WHERE id = ? AND status = 'running'",
);
const failStmt = db.prepare(
  "UPDATE jobs SET status = 'failed', progress = 0, output = NULL, error = ?, updated_at = ? WHERE id = ? AND status = 'running'",
);
const requeueStmt = db.prepare(
  "UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, attempts = MAX(attempts - 1, 0), updated_at = ? WHERE id = ? AND status = 'running'",
);

function claimNext(): JobRow | undefined {
  db.exec('BEGIN IMMEDIATE');
  try {
    const row = pickStmt.get(Date.now()) as JobRow | undefined;
    if (row) claimStmt.run(now(), row.id);
    db.exec('COMMIT');
    return row ? (getStmt.get(row.id) as unknown as JobRow) : undefined;
  } catch (err) {
    db.exec('ROLLBACK');
    throw err;
  }
}

async function processJob(job: JobRow): Promise<void> {
  const attempt = job.attempts;
  console.log(`job ${job.id}: attempt ${attempt}`);
  for (let step = 1; step <= job.steps; step++) {
    if (step === 1 && attempt <= job.fail_attempts) {
