import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { openDatabase, toJob, type JobRow } from './db.ts';

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const MAX_BODY = 1024 * 1024;
const KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError {
  field: string;
  message: string;
}

class HttpError extends Error {
  constructor(
    public status: number,
    public code: string,
    message: string,
    public fields?: FieldError[],
  ) {
    super(message);
  }
}

function send(res: ServerResponse, status: number, body: unknown, extraHeaders: Record<string, string> = {}): void {
  const data = JSON.stringify(body);
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(data),
    'cache-control': 'no-store',
    ...extraHeaders,
  });
  res.end(data);
}

function sendError(res: ServerResponse, err: HttpError): void {
  const error: Record<string, unknown> = { code: err.code, message: err.message };
  if (err.fields) error.fields = err.fields;
  const headers: Record<string, string> = {};
  send(res, err.status, { error }, headers);
}

function readBody(req: IncomingMessage): Promise<{ text: string; tooLarge: boolean }> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve({ text: Buffer.concat(chunks).toString('utf8'), tooLarge }));
    req.on('error', reject);
  });
}

const stmts = {
  list: db.prepare('SELECT * FROM jobs ORDER BY seq DESC'),
  get: db.prepare('SELECT * FROM jobs WHERE id = ?'),
  byKey: db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?'),
  insert: db.prepare(
    `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, idempotency_key, run_after, created_at, updated_at)
     VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
  ),
  heartbeat: db.prepare('SELECT beat_at FROM heartbeat WHERE id = 1'),
};

interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

function validate(req: IncomingMessage, raw: { text: string; tooLarge: boolean }): { payload: Payload; key: string | null } {
  const fields: FieldError[] = [];
  const keyHeader = req.headers['idempotency-key'];
  let key: string | null = null;
  if (keyHeader !== undefined) {
    const value = Array.isArray(keyHeader) ? keyHeader.join(',') : keyHeader;
    if (!KEY_RE.test(value)) {
      fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
    } else key = value;
  }

  const contentType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  const isJson = contentType === 'application/json' || /^application\/[a-z0-9.+-]+\+json$/.test(contentType);
  let body: unknown;
  let bodyOk = false;
  if (!isJson) {
    fields.push({ field: 'Content-Type', message: 'must be application/json' });
    fields.push({ field: 'body', message: 'request body must be sent as application/json' });
  } else if (raw.tooLarge) {
    fields.push({ field: 'body', message: 'request body is too large' });
  } else {
    try {
      body = JSON.parse(raw.text);
      if (body === null || typeof body !== 'object' || Array.isArray(body)) {
        fields.push({ field: 'body', message: 'must be a JSON object' });
      } else bodyOk = true;
    } catch {
      fields.push({ field: 'body', message: 'must be valid JSON' });
    }
  }

  const payload: Payload = { input: '', steps: 5, failAttempts: 0 };
  if (bodyOk) {
    const obj = body as Record<string, unknown>;
    for (const name of Object.keys(obj)) {
      if (!['input', 'steps', 'failAttempts'].includes(name)) {
        fields.push({ field: name, message: 'unknown field' });
      }
    }
    if (!Object.hasOwn(obj, 'input')) {
      fields.push({ field: 'input', message: 'is required' });
    } else if (typeof obj.input !== 'string') {
      fields.push({ field: 'input', message: 'must be a string' });
    } else if (obj.input.length < 1 || obj.input.length > 1000) {
      fields.push({ field: 'input', message: 'must be 1 to 1000 characters' });
    } else if (obj.input.trim() === '') {
      fields.push({ field: 'input', message: 'must not be only whitespace' });
    } else payload.input = obj.input;

    const intField = (name: 'steps' | 'failAttempts', min: number, max: number) => {
      if (!Object.hasOwn(obj, name)) return;
      const v = obj[name];
      if (typeof v !== 'number' || !Number.isInteger(v) || v < min || v > max) {
        fields.push({ field: name, message: `must be an integer from ${min} to ${max}` });
      } else payload[name] = v;
    };
    intField('steps', 1, 20);
    intField('failAttempts', 0, 5);
  }

  if (fields.length > 0) throw new HttpError(400, 'invalid_request', 'The request is invalid.', fields);
  return { payload, key };
}

function createJob(payload: Payload, key: string | null): { status: number; job: JobRow } {
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== null) {
      const existing = stmts.byKey.get(key) as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        if (
          existing.input === payload.input &&
          existing.steps === payload.steps &&
          existing.fail_attempts === payload.failAttempts
        ) {
          return { status: 200, job: existing };
        }
        throw new HttpError(409, 'idempotency_conflict', 'Idempotency-Key was already used with a different payload.');
      }
    }
    const id = randomUUID();
    const ts = new Date().toISOString();
    stmts.insert.run(id, payload.input, payload.steps, payload.failAttempts, key, ts, ts);
    db.exec('COMMIT');
    return { status: 201, job: stmts.get.get(id) as unknown as JobRow };
  } catch (err) {
    if (db.isTransaction) db.exec('ROLLBACK');
    throw err;
  }
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';
  const allow = (methods: string[]) => {
    if (!methods.includes(method)) {
      throw new HttpError(405, 'method_not_allowed', `Method ${method} is not allowed on ${pathname}.`);
    }
  };

  if (pathname === '/') {
    allow(['GET', 'HEAD']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' });
    res.end(method === 'HEAD' ? undefined : uiHtml);
    return;
  }
  if (pathname === '/health') {
    allow(['GET']);
    const row = stmts.heartbeat.get() as { beat_at: number } | undefined;
    const up = row !== undefined && Date.now() - row.beat_at < 3000;
    return send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
  }
  if (pathname === '/api/jobs') {
    allow(['GET', 'POST']);
    if (method === 'GET') {
      const rows = stmts.list.all() as unknown as JobRow[];
      return send(res, 200, { jobs: rows.map(toJob) });
    }
    const raw = await readBody(req);
    const { payload, key } = validate(req, raw);
    const { status, job } = createJob(payload, key);
    return send(res, status, toJob(job));
  }
  const m = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (m) {
    allow(['GET']);
    let id: string;
    try {
      id = decodeURIComponent(m[1]!);
    } catch {
      id = m[1]!;
    }
    const row = stmts.get.get(id) as JobRow | undefined;
    if (!row) throw new HttpError(404, 'not_found', `Job ${id} was not found.`);
    return send(res, 200, toJob(row));
  }
  throw new HttpError(404, 'not_found', `No route for ${pathname}.`);
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  handle(req, res).catch((err: unknown) => {
    if (err instanceof HttpError) return sendError(res, err);
    console.error(err);
    if (!res.headersSent) sendError(res, new HttpError(500, 'internal_error', 'Internal server error.'));
    else res.end();
  });
});
server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
  setTimeout(() => process.exit(0), 3000).unref();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

